struct {
    opaque did_log<V>;
    opaque witness_file<V>;
} DIDWebVHCredential;

struct {
    CredentialType credential_type;
    select (Credential.credential_type) {
        case basic:
            opaque identity<V>;
        case x509:
            Certificate certificates<V>;
        case did_webvh:
            DIDWebVHCredential did_webvh;
    };
} Credential;

struct {
    opaque scid<V>;
    opaque version_id<V>;
    SignaturePublicKey authorized_keys<V>;
} DIDWebVHHead;

struct {
    DIDWebVHHead heads<V>;
} DIDWebVHHeads;
